const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),stage=document.querySelector('#stage'),overlay=document.querySelector('#overlay'),title=document.querySelector('#title'),description=document.querySelector('#description'),roomForm=document.querySelector('#room-form'),codeInput=document.querySelector('#code'),connection=document.querySelector('#connection'),roomLabel=document.querySelector('#room-label'),roomToggle=document.querySelector('#room-toggle'),again=document.querySelector('#again'),weaponEl=document.querySelector('#weapon'),upgradeEl=document.querySelector('#upgrade'),healthEl=document.querySelector('#health'),bossBar=document.querySelector('#boss-bar'),goalLabel=document.querySelector('#goal-label'),fuelLabel=document.querySelector('#fuel-label');
const W=960,H=540,weapons=['Pistol','AK','Rapid Blaster','Star Cannon'],thresholds=[10,30,60],keys=new Set(),pointers=new Map();let socket=null,playerId=null,state=null,roomCode='',manualAim=null,screenFire=false,lastState='',cameraX=0,codeVisible=true;
function randomCode(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',arr=new Uint8Array(6);crypto.getRandomValues(arr);return [...arr].map(v=>chars[v%chars.length]).join('')}
function resetInputs(){keys.clear();pointers.clear();screenFire=false;manualAim=null;document.querySelectorAll('.pressed').forEach(e=>e.classList.remove('pressed'))}
function showOverlay(heading,text,showRoom){overlay.hidden=false;stage.classList.add('intro');title.textContent=heading;description.textContent=text;roomForm.hidden=!showRoom;again.hidden=showRoom;resetInputs()}
function connect(code){code=code.trim().toUpperCase();if(!/^[A-Z0-9]{4,8}$/.test(code)){connection.textContent='Use a room code with 4–8 letters or numbers.';return}if(socket){socket.close();socket=null}roomCode=code;codeInput.value=code;playerId=null;state=null;lastState='';connection.textContent='Connecting to room '+code+'…';const protocol=location.protocol==='https:'?'wss:':'ws:',ws=new WebSocket(`${protocol}//${location.host}/api/bean/${code}`);socket=ws;
 ws.addEventListener('message',event=>{if(socket!==ws)return;try{const msg=JSON.parse(event.data);if(msg.type==='joined'){playerId=msg.id;codeVisible=true;roomToggle.hidden=false;refreshCodeToggle();connection.textContent='Connected!';roomLabel.textContent='ROOM '+code;overlay.hidden=true;stage.classList.remove('intro')}else if(msg.type==='snapshot'){state=msg;updateUI()}}catch{}});
 ws.addEventListener('error',()=>{if(socket===ws)connection.textContent='Could not connect. Please try again.'});ws.addEventListener('close',()=>{if(socket!==ws)return;socket=null;playerId=null;state=null;roomToggle.hidden=true;roomLabel.textContent='Disconnected';showOverlay('Connection lost','Check your connection and create or rejoin a room.',true);connection.textContent='Your room code was '+roomCode+'.'})}
function refreshCodeToggle(){roomToggle.textContent=codeVisible?'Hide':'Show';roomToggle.setAttribute('aria-label',codeVisible?'Hide room code':'Show room code');if(state)roomLabel.textContent=codeVisible?`ROOM ${roomCode} · ${state.players.length}/8`:`ROOM HIDDEN · ${state.players.length}/8`}
roomToggle.addEventListener('click',()=>{codeVisible=!codeVisible;refreshCodeToggle()});
function updateUI(){if(!state)return;const me=state.players.find(p=>p.id===playerId);if(me){weaponEl.textContent=weapons[me.weapon];upgradeEl.textContent=me.weapon<3?`${Math.max(0,thresholds[me.weapon]-me.hits)} hits to ${weapons[me.weapon+1]}`:'Max upgrade!';healthEl.textContent='♥ '.repeat(me.hp)+'♡ '.repeat(5-me.hp);healthEl.setAttribute('aria-label',`${me.hp} of 5 hearts`)}bossBar.style.width=state.phase==='boss'?`${Math.max(0,state.boss.hp/state.boss.maxHp*100)}%`:`${state.distance/state.destination*100}%`;goalLabel.textContent=state.phase==='boss'?'🫘 BEAN BOSS':`🚂 TRAIN ${Math.floor(state.distance)} / ${state.destination}`;fuelLabel.textContent=state.phase==='boss'?'FINAL BOSS':state.fuel>0?`FUEL ${Math.ceil(state.fuel)} / ${state.maxFuel}`:'NO FUEL — COLLECT FUEL!';roomLabel.textContent=codeVisible?`ROOM ${roomCode} · ${state.players.length}/8`:`ROOM HIDDEN · ${state.players.length}/8`;
 if(state.status!==lastState){lastState=state.status;if(state.status==='won')showOverlay('You beat the Bean Boss! 🎉','Amazing teamwork! The bean has been defeated.',false);else if(state.status==='lost')showOverlay('The bean wins this round!','Everyone is out. Try again together!',false);else if(state.status==='playing'&&playerId){overlay.hidden=true;stage.classList.remove('intro')}}}
function sendInput(){if(!socket||socket.readyState!==WebSocket.OPEN||!state||!playerId)return;const me=state.players.find(p=>p.id===playerId);if(!me)return;const has=name=>keys.has(name)||[...pointers.values()].includes(name);let dx=(has('right')?1:0)-(has('left')?1:0),dy=(has('down')?1:0)-(has('up')?1:0);const nearby=state.enemies.length?state.enemies.reduce((a,b)=>Math.hypot(a.x-me.x,a.y-me.y)<Math.hypot(b.x-me.x,b.y-me.y)?a:b):null,target=manualAim||nearby||state.boss||{x:me.x+1,y:me.y},ax=target.x-me.x,ay=target.y-me.y,l=Math.hypot(ax,ay)||1;socket.send(JSON.stringify({type:'input',dx,dy,aimX:ax/l,aimY:ay/l,fire:state.status==='playing'&&me.hp>0&&(has('fire')||screenFire)}))}
setInterval(sendInput,80);
function roundRect(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function render(){const viewWidth=matchMedia('(max-width:600px)').matches?720:960;if(canvas.width!==viewWidth)canvas.width=viewWidth;const me=state?.players.find(p=>p.id===playerId);cameraX=viewWidth<W?clamp((me?.x??W/2)-viewWidth/2,0,W-viewWidth):0;ctx.clearRect(0,0,canvas.width,H);ctx.save();ctx.translate(-cameraX,0);ctx.fillStyle='#f6d5af';ctx.fillRect(0,0,W,H);const shift=(state?.distance||0)*2;ctx.fillStyle='#d6a269';for(let i=-1;i<15;i++){const x=((i*100-shift)%1100+1100)%1100-70;roundRect(x,70+(i%3)*12,38,15,7,'#ddb79d');roundRect(x+50,440-(i%3)*15,21,30,6,'#a2c99d')}
 ctx.fillStyle='#967c83';ctx.fillRect(0,176,W,9);ctx.fillRect(0,355,W,9);for(let i=-1;i<18;i++){const x=((i*65-shift)%1100+1100)%1100-70;roundRect(x,165,15,210,3,'#b9978e')}
 roundRect(142,199,578,142,18,'#655876');roundRect(151,207,560,126,14,'#b5a4d0');roundRect(165,217,245,106,10,'#f9e6d1');roundRect(421,217,160,106,10,'#fff0dc');roundRect(593,214,118,112,15,'#a9dcdf');roundRect(650,227,43,83,8,'#82bec4');roundRect(608,228,30,26,5,'#eafcff');roundRect(608,277,30,26,5,'#eafcff');ctx.fillStyle='#52445e';for(const x of [190,355,455,550,625,695]){ctx.beginPath();ctx.arc(x,206,9,0,Math.PI*2);ctx.arc(x,335,9,0,Math.PI*2);ctx.fill()}
 if(state){const boss=state.boss;if(boss){ctx.save();ctx.translate(boss.x,boss.y);ctx.rotate(-.3);ctx.fillStyle='#a74b41';ctx.beginPath();ctx.ellipse(0,0,44,53,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d87d65';ctx.beginPath();ctx.ellipse(-8,-8,33,41,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#392a3d';ctx.beginPath();ctx.arc(-12,-4,4,0,Math.PI*2);ctx.arc(12,-4,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#392a3d';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,5,8,.1,Math.PI-.1);ctx.stroke();ctx.restore()}for(const e of state.enemies){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#619568';ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#345443';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#2d3e36';ctx.fillRect(-10,-5,5,5);ctx.fillRect(5,-5,5,5);ctx.fillRect(-6,6,12,3);ctx.restore()}for(const fuel of state.pickups){roundRect(fuel.x-13,fuel.y-15,26,30,5,'#ffc96f');ctx.fillStyle='#684b3d';ctx.textAlign='center';ctx.font='bold 17px system-ui';ctx.fillText('⛽',fuel.x,fuel.y+6)}for(const shot of state.beanShots){ctx.fillStyle='#eb8b74';ctx.beginPath();ctx.arc(shot.x,shot.y,8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff5d5';ctx.lineWidth=2;ctx.stroke()}for(const shot of state.bullets){ctx.fillStyle=['#ffe37d','#a1e6ff','#eabaff','#fff5a2'][shot.weapon]||'#ffe37d';ctx.beginPath();ctx.arc(shot.x,shot.y,shot.weapon===3?7:5,0,Math.PI*2);ctx.fill()}
 for(const p of state.players){ctx.save();ctx.translate(p.x,p.y);if(p.hp<=0)ctx.globalAlpha=.35;else if(p.invulnerable&&Math.floor(performance.now()/100)%2)ctx.globalAlpha=.55;ctx.rotate(Math.atan2(p.aimY,p.aimX));roundRect(4,-5,27,10,4,'#424362');ctx.rotate(-Math.atan2(p.aimY,p.aimX));ctx.fillStyle='#38404f';ctx.beginPath();ctx.ellipse(-13,17,8,7,-.2,0,Math.PI*2);ctx.ellipse(13,17,8,7,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(-13,16,6,5,-.2,0,Math.PI*2);ctx.ellipse(13,16,6,5,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#38404f';ctx.beginPath();ctx.ellipse(0,0,23,24,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(0,-1,20,21,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff2e4';ctx.beginPath();ctx.ellipse(0,2,16,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#38404f';ctx.beginPath();ctx.ellipse(-6,-1,3.5,5,0,0,Math.PI*2);ctx.ellipse(6,-1,3.5,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-5,-3,1.4,0,Math.PI*2);ctx.arc(7,-3,1.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f4a5aa';ctx.beginPath();ctx.ellipse(-11,6,3,1.7,0,0,Math.PI*2);ctx.ellipse(11,6,3,1.7,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#38404f';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(0,5,3,0,Math.PI);ctx.stroke();ctx.restore();ctx.textAlign='center';ctx.fillStyle='#3d4260';ctx.font='bold 13px system-ui';ctx.fillText(p.id===playerId?'YOU':'FRIEND',p.x,p.y-30);if(p.hp<=0){ctx.font='bold 13px system-ui';ctx.fillText('OUT',p.x,p.y+40)}}}
 ctx.restore();requestAnimationFrame(render)}
const map={w:'up',arrowup:'up',s:'down',arrowdown:'down',a:'left',arrowleft:'left',d:'right',arrowright:'right',' ':'fire'};window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;const key=map[e.key.toLowerCase()];if(key){e.preventDefault();keys.add(key)}});window.addEventListener('keyup',e=>{const key=map[e.key.toLowerCase()];if(key)keys.delete(key)});window.addEventListener('blur',resetInputs);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInputs()});
for(const button of document.querySelectorAll('[data-move],#fire')){const name=button.dataset.move||'fire';button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);pointers.set(e.pointerId,name);button.classList.add('pressed')});const release=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(name))button.classList.remove('pressed')};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)}
function aim(e){const r=canvas.getBoundingClientRect();manualAim={x:clamp((e.clientX-r.left)/r.width*canvas.width+cameraX,0,W),y:clamp((e.clientY-r.top)/r.height*H,0,H)}}function clamp(v,a,b){return Math.max(a,Math.min(b,v))}canvas.addEventListener('pointerdown',e=>{if(!state||state.status!=='playing')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);aim(e);screenFire=true});canvas.addEventListener('pointermove',e=>{if(screenFire)aim(e)});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{screenFire=false;manualAim=null});
document.querySelector('#create').addEventListener('click',()=>connect(randomCode()));document.querySelector('#join').addEventListener('click',()=>connect(codeInput.value));again.addEventListener('click',()=>{if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'restart'}))});stage.classList.add('intro');requestAnimationFrame(render);
